import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


# ----------------------------------------------------------------------
# Custom CUDA operator for element-wise addition (a + b)
# ----------------------------------------------------------------------
elementwise_add_cpp_source = (
    "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"
)
elementwise_add_cuda_source = """
__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float()>, b.data_ptr<float()>, out.data_ptr<float()>, size);

    return out;
}
"""

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_cuda_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


# ----------------------------------------------------------------------
# Custom CUDA operator for matrix-vector multiplication (A @ B)
#   A: (M, K), B: (K, 1) -> C: (M, 1)
# ----------------------------------------------------------------------
elementmatmul_cpp_source = (
    "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"
)
elementmatmul_cuda_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Delegate to PyTorch's native matmul on the device
    return A.matmul(B);
}
"""

elementmatmul = load_inline(
    name="matmul_cuda",
    cpp_sources=elementmatmul_cpp_source,
    cuda_sources=elementmatmul_cuda_source,
    functions=["matmul_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[],
)


class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add
        self.matmul_cuda = elementmatmul

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        """
        Performs matrix-vector multiplication (C = A * B).

        Args:
            A: Input matrix of shape (M, K).
            B: Input vector of shape (K, 1).

        Returns:
            Output vector of shape (M, 1).
        """
        return self.matmul_cuda(A, B)
